payload.input:
const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat \"$STAMPED_ASSESSMENT_VERSION\"; cat \"$STAMPED_DELIVERY_MANIFEST\"; cat \"$STAMPED_OPERATIONAL_MANIFEST\"; cat \"$STAMPED_WORKER_STOP_RECEIPT\"","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"find \"$(dirname \"$STAMPED_DELIVERY_MANIFEST\")\" -maxdepth 1 -type f -print; find \"$(dirname \"$STAMPED_WORKER_STOP_RECEIPT\")\" -maxdepth 3 -iname 'judge-target.json' -o -iname '*guidance*'","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" --help","yield_time_ms":10000,"max_output_tokens":6000}),
  tools.exec_command({cmd:"rg --files --hidden --no-ignore \"$STAMPED_JUDGE_TARGET\"","yield_time_ms":10000,"max_output_tokens":8000})
]);
for (const x of results) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

