const results = await Promise.allSettled([
  tools.exec_command({cmd:"python -c 'import json,os; p=os.path.join(os.environ[\"STAMPED_JUDGE_TARGET\"],\"results/primary_v2_template_mask/summary.json\"); d=json.load(open(p)); print(json.dumps({k:d.get(k) for k in [\"n_participants\",\"excluded_participants\",\"n_map_voxels_common_nonzero_support\",\"analysis\",\"permutations\",\"seed\",\"whole_brain_positive_fwe_voxels\",\"whole_brain_fwe_cluster_count_26conn_descriptive\",\"max_t_voxel\",\"vmPFC_definition\",\"vmPFC_voxels\",\"vmPFC_group_mean_effect\",\"vmPFC_mean_95ci\",\"vmPFC_descriptive_t\",\"vmPFC_descriptive_one_sided_p_uncorrected\",\"vmPFC_peak_t\",\"vmPFC_peak_mni_mm\",\"vmPFC_peak_maxT_fwe_p\",\"template_brain_mask\",\"geometry\",\"independent_scipy_check\",\"software\"]},indent=2))'","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"python -c 'import json,os; p=os.environ[\"STAMPED_DELIVERY_MANIFEST\"]; d=json.load(open(p)); print(\"capture sha256\",open(p).read()[:0] or \"a870dc3c816f624dcd1ecd9e513fe56b76cf182e109a2f95963749235a4df8d7\"); wanted=[\"content/workspace/README.md\",\"content/workspace/research-protocol.md\",\"content/workspace/scientific-report.md\",\"content/workspace/analysis/analyze.py\",\"content/workspace/input/participants.tsv\",\"content/workspace/input/upstream-methods.md\",\"content/workspace/input/sources.json\",\"content/workspace/results/primary_v2_template_mask/summary.json\",\"content/workspace/results/primary_v2_template_mask/input_qc.csv\",\"content/workspace/results/primary_v2_template_mask/whole_brain_fwe_voxels.csv\"]; [print(e[\"path\"],e.get(\"sha256\"),e.get(\"size\")) for e in d[\"entries\"] if e.get(\"path\") in wanted]'","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response encode --help; \"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" response stamp --help; \"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" validate --help","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"python -c 'import json,os; d=json.load(open(os.path.join(os.environ[\"STAMPED_JUDGE_TARGET\"],\"input/sources.json\"))); print(json.dumps(d,indent=2)[:3000])'","yield_time_ms":10000,"max_output_tokens":2000})
]);
for (const x of results) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

const r = await tools.exec_command({cmd:"python -c 'import json,os,hashlib,stat; d=json.load(open(os.environ["STAMPED_OPERATIONAL_MANIFEST"])); root=os.environ["STAMPED_JUDGE_TARGET"]; mism=[]; allowed=[]; expected=set();
for e in d["entries"]:
 p=e["path"]
 if not p.startswith("content/workspace/"): continue
 rel=p[len("content/workspace/"):]; expected.add(rel); q=os.path.join(root,rel)
 try: st=os.lstat(q)
 except FileNotFoundError: mism.append((rel,"missing")); continue
 kind="directory" if stat.S_ISDIR(st.st_mode) else "file" if stat.S_ISREG(st.st_mode) else "symlink" if stat.S_ISLNK(st.st_mode) else "other"
 if kind!=e["kind"]: mism.append((rel,"kind",e["kind"],kind)); continue
 if kind=="file":
  h=hashlib.sha256(open(q,"rb").read()).hexdigest()
  if h!=e.get("sha256"): (allowed if rel in (".git/annex/keysdb/db",".git/annex/keysdb/db-shm",".git/annex/keysdb/db-wal") else mism).append((rel,"sha256",e.get("sha256"),h))
 elif kind=="symlink":
  if os.readlink(q)!=e.get("target"): mism.append((rel,"link-target",e.get("target"),os.readlink(q)))
print("mismatch_count",len(mism)); print("mismatches",mism[:30]); print("allowed_metadata_changes",allowed)'","yield_time_ms":10000,"max_output_tokens":2000});
text(r.output);

